-- ============================================================================
-- GetFittWithMohit — Nutrition: plans, versions and starter templates
--
-- Run this ENTIRE file in the Supabase SQL Editor, in one go. Safe to re-run.
-- Requires supabase/nutrition_foods.sql (the food list) and
-- supabase/courses_and_audios.sql (gfm_is_coach()).
--
-- nutrition_plans: one row per client plan (client_id set) or template
--   (client_id null). `draft` is what the coach edits; `published` is what the
--   client sees. Publishing copies draft → published and keeps a snapshot in
--   nutrition_plan_versions, so any version can be restored.
-- Coach only (RLS). Clients read their published plan through /api/me/nutrition,
-- so a half-finished draft can never reach them.
--
-- To undo: supabase/nutrition_plans_rollback.sql
-- ============================================================================

create table if not exists public.nutrition_plans (
  id              uuid primary key default gen_random_uuid(),
  client_id       uuid references public.clients(id) on delete cascade,
  name            text not null,
  diet            text, -- templates: Vegetarian | Eggetarian | Non-vegetarian | Jain | Vegan
  draft           jsonb not null,
  published       jsonb,
  version         integer not null default 0,
  published_at    timestamptz,
  change_note     text,
  status          text not null default 'active' check (status in ('active', 'archived')),
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);

-- One active plan per client
create unique index if not exists nutrition_plans_one_active
  on public.nutrition_plans (client_id) where status = 'active' and client_id is not null;
create index if not exists nutrition_plans_templates on public.nutrition_plans (status) where client_id is null;

create table if not exists public.nutrition_plan_versions (
  id            uuid primary key default gen_random_uuid(),
  plan_id       uuid not null references public.nutrition_plans(id) on delete cascade,
  version       integer not null,
  doc           jsonb not null,
  change_note   text,
  published_at  timestamptz not null default now(),
  unique (plan_id, version)
);

alter table public.nutrition_plans enable row level security;
alter table public.nutrition_plan_versions enable row level security;
drop policy if exists "coach full access" on public.nutrition_plans;
create policy "coach full access" on public.nutrition_plans
  for all using (public.gfm_is_coach()) with check (public.gfm_is_coach());
drop policy if exists "coach full access" on public.nutrition_plan_versions;
create policy "coach full access" on public.nutrition_plan_versions
  for all using (public.gfm_is_coach()) with check (public.gfm_is_coach());

-- ── Starter templates (one per diet). Assigning one to a client scales every
-- portion to that client's calorie target. Re-running never duplicates them.
